import React, { useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Album, Track } from '../catalog/catalog';
import { titleFromFilename } from '../catalog/titles';
import { usePulseTarget } from '../hooks/usePulseTarget';
import { toggleFullscreen } from '../shell/fullscreen';
import { PlaybackControls, PlaybackState } from '../types/playback';
import { DEFAULT_RIPPLE_SETTINGS, RippleSettings } from '../visuals/ripples';
import TimeSlider from './TimeSlider';
import DockSlider from './DockSlider';
import DownloadDialog from './DownloadDialog';
import ShareDialog from './ShareDialog';
import { MIXER_SLIDERS, formatPercent, sliderValue } from './mixer/mixerControls';
import { UserSettings } from './UserProvider';
import {
  IconDownload,
  IconFullscreen,
  IconNext,
  IconPause,
  IconPlay,
  IconPrev,
  IconRepeat,
  IconShare,
  IconShuffle,
} from './icons';

interface DockProps {
  playback: PlaybackState;
  controls: PlaybackControls;
  track: Track | null;
  album: Album | null;
  settings: Partial<UserSettings>;
  onShowInAlbums: (albumId: string) => void;
  showFullscreen: boolean;
  /** The dock has faded out for idle; sparks stop spawning so none float over an empty screen. */
  faded?: boolean;
}

const SPEED = MIXER_SLIDERS.find((def) => def.id === 'tempo')!;

/** Title for a song that is not in the catalog, derived from its URL. */
function fallbackTitle(songUrl: string | null): string {
  if (!songUrl) return 'Nothing playing';
  const file = songUrl.split('/').pop() || '';
  try {
    return titleFromFilename(decodeURIComponent(file));
  } catch {
    return titleFromFilename(file);
  }
}

/** Maps user settings to the slider particle props. */
function sparkSettings(settings: Partial<UserSettings>, faded: boolean) {
  return {
    particleEnabled: !faded && (settings.sliderSparksEnabled ?? false),
    particleSpawnRate: settings.particleSpawnRate,
    particleLifespan: settings.particleLifespan,
    particleBaseAngle: settings.particleBaseAngle,
    particleAngleSpread: settings.particleAngleSpread,
    particleSpeed: settings.particleSpeed,
    particleSpeedVariance: settings.particleSpeedVariance,
    particleGravity: settings.particleGravity,
    particleFadeMode: settings.particleFadeMode,
  };
}

/** Maps user settings to the time slider's ripple settings; null while off or faded out. */
function rippleSettings(settings: Partial<UserSettings>, faded: boolean): RippleSettings | null {
  if (faded || settings.sliderRipplesEnabled === false) return null;
  return {
    heightPx: settings.rippleHeight ?? DEFAULT_RIPPLE_SETTINGS.heightPx,
    speedPxPerSec: settings.rippleSpeed ?? DEFAULT_RIPPLE_SETTINGS.speedPxPerSec,
    sensitivity: settings.rippleSensitivity ?? DEFAULT_RIPPLE_SETTINGS.sensitivity,
  };
}

/** Play/pause with the audio-reactive glow, written straight to a CSS variable (no re-renders). */
function PlayPauseButton({
  paused,
  disabled,
  onClick,
}: {
  paused: boolean;
  disabled: boolean;
  onClick: () => void;
}) {
  const ref = useRef<HTMLButtonElement>(null);
  usePulseTarget(ref, '--pulse-intensity', !paused && !disabled);
  const label = paused ? 'Play' : 'Pause';
  return (
    <button
      ref={ref}
      className="Dock-button Dock-play"
      aria-label={label}
      title={`${label} (Space)`}
      onClick={onClick}
      disabled={disabled}
    >
      {paused ? <IconPlay /> : <IconPause />}
    </button>
  );
}

/** An icon toggle whose on state is an accent fill plus a dot. */
function ModeToggle({
  label,
  on,
  onClick,
  children,
}: {
  label: string;
  on: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      className={`Dock-button Dock-toggle${on ? ' is-on' : ''}`}
      aria-label={label}
      aria-pressed={on}
      title={label}
      onClick={onClick}
    >
      {children}
    </button>
  );
}

/** Floating transport bar: controls, now playing, progress, modes, speed, volume and fullscreen. */
export default function Dock({
  playback,
  controls,
  track,
  album,
  settings,
  onShowInAlbums,
  showFullscreen,
  faded = false,
}: DockProps) {
  const disabled = playback.ejected;
  const title = track ? track.title : fallbackTitle(playback.songUrl);
  const regionRef = useRef<HTMLDivElement>(null);
  usePulseTarget(regionRef, '--pulse-intensity', !playback.paused && !disabled);
  // The dialog keeps the track it was opened for, so an export survives playback moving on.
  const [download, setDownload] = useState<{
    songUrl: string;
    title: string;
    album: string | null;
  } | null>(null);
  const downloadButtonRef = useRef<HTMLButtonElement>(null);
  const canDownload = !disabled && !playback.stubMode && !!playback.songUrl;
  const [share, setShare] = useState<{ trackId: string; title: string; positionMs: number } | null>(
    null
  );
  const shareButtonRef = useRef<HTMLButtonElement>(null);

  return (
    <div ref={regionRef} className="Dock Chrome" role="region" aria-label="Player">
      <div className="Dock-transport">
        <button
          className="Dock-button"
          aria-label="Previous track"
          title="Previous (Left arrow)"
          onClick={controls.prevTrack}
          disabled={disabled}
        >
          <IconPrev />
        </button>
        <PlayPauseButton
          paused={playback.paused}
          disabled={disabled}
          onClick={controls.togglePause}
        />
        <button
          className="Dock-button"
          aria-label="Next track"
          title="Next (Right arrow)"
          onClick={controls.nextTrack}
          disabled={disabled}
        >
          <IconNext />
        </button>
      </div>

      <button
        className="Dock-meta"
        onClick={() => album && onShowInAlbums(album.id)}
        disabled={!album}
        title={album ? 'Show in Albums' : undefined}
      >
        <span className="Dock-title">{title}</span>
        {album && <span className="Dock-album">{album.title}</span>}
      </button>

      <div className="Dock-progress">
        <TimeSlider
          paused={playback.paused || playback.ejected}
          currentSongDurationMs={playback.durationMs}
          getCurrentPositionMs={controls.getPositionMs}
          onChange={controls.seekToFraction}
          looping={playback.repeat}
          {...sparkSettings(settings, faded)}
          ripples={rippleSettings(settings, faded)}
        />
      </div>

      <div className="Dock-modes">
        <ModeToggle
          label="Shuffle"
          on={playback.shuffle}
          onClick={() => controls.setShuffle(!playback.shuffle)}
        >
          <IconShuffle />
        </ModeToggle>
        <ModeToggle
          label="Repeat track"
          on={playback.repeat}
          onClick={() => controls.setRepeat(!playback.repeat)}
        >
          <IconRepeat />
        </ModeToggle>
        <button
          ref={downloadButtonRef}
          className="Dock-button"
          aria-label="Download track"
          title={playback.stubMode ? 'Download needs the audio engine' : 'Download track'}
          onClick={() =>
            playback.songUrl &&
            setDownload({
              songUrl: playback.songUrl,
              title,
              album: album ? album.title : null,
            })
          }
          disabled={!canDownload}
        >
          <IconDownload />
        </button>
        <button
          ref={shareButtonRef}
          className="Dock-button"
          aria-label="Share track"
          title="Share this song with your mix"
          onClick={() =>
            track && setShare({ trackId: track.id, title, positionMs: controls.getPositionMs() })
          }
          disabled={disabled || !track}
        >
          <IconShare />
        </button>
      </div>

      <div className="Dock-sliders">
        <div className="Dock-speed">
          <DockSlider
            label={SPEED.label}
            value={sliderValue(SPEED, playback, settings)}
            min={SPEED.min}
            max={SPEED.max}
            step={SPEED.step}
            format={formatPercent}
            onChange={controls.setTempo}
            resetValue={SPEED.defaultValue}
          />
        </div>

        <div className="Dock-volume">
          <DockSlider
            label="Volume"
            value={playback.volume}
            min={0}
            max={150}
            step={1}
            format={(value) => `${value}%`}
            onChange={controls.setVolume}
            resetValue={100}
          />
        </div>
      </div>

      {showFullscreen && (
        <button
          className="Dock-button"
          aria-label="Fullscreen"
          title="Fullscreen (F)"
          onClick={() => toggleFullscreen()}
        >
          <IconFullscreen />
        </button>
      )}

      {download &&
        // Portaled so the dialog escapes the Dock's idle fade and layout.
        createPortal(
          <DownloadDialog
            title={download.title}
            album={download.album}
            songUrl={download.songUrl}
            playback={playback}
            settings={settings}
            onClose={() => {
              setDownload(null);
              downloadButtonRef.current?.focus();
            }}
          />,
          document.body
        )}

      {share &&
        createPortal(
          <ShareDialog
            title={share.title}
            trackId={share.trackId}
            positionMs={share.positionMs}
            playback={playback}
            settings={settings}
            onClose={() => {
              setShare(null);
              shareButtonRef.current?.focus();
            }}
          />,
          document.body
        )}
    </div>
  );
}
